"""Share coordinate fields while preserving each caller's original contract.

Paths are still constructed and certified from the caller's own live sources.
Guide narrowing and explicit clearance ratios retain their exact arithmetic
and separate validation branches. Nothing is cached across call contexts.
"""
import bpy

from . import curved_sector_coordinates as coordinates
from . import curved_junction_nodes as boundary

c = boundary.c
PREFIXES = (coordinates.NAME, 'Prochitecture Streets / Clearance sector coordinates v2',
            'Prochitecture Streets / Prepared clearance sector coordinates v1')


def interface(tree):
    return [(s.identifier, s.name, s.in_out, s.socket_type)
            for s in tree.interface.items_tree if s.item_type == 'SOCKET']


def build(*, external_ratio=False, prepared_paths=False, continuations=False, span_compounds=False,
          interpolation=False):
    if continuations == span_compounds:
        raise ValueError('Choose one qualified original-port boundary family')
    family = dict(allow_taper=True, port_paths=True, continuations=continuations,
                  span_compounds=span_compounds, interpolation=interpolation)
    original = coordinates.build(external_ratio=external_ratio, prepared_paths=prepared_paths, **family)
    name = original.name+' / Shared coordinates v1'
    if name in bpy.data.node_groups:
        return bpy.data.node_groups[name]
    core = coordinates.build(external_ratio=True, prepared_paths=True, _shared_core=True, **family)
    tree = original.copy(); tree.name = name; tree.nodes.clear()
    # Attach the established field DSL to the copied interface. Recreating its
    # sockets could change identifiers on already-bound caller group nodes.
    g = c.Graph.__new__(c.Graph); g.g = tree; g.count = 0; g.frame = None
    inp = g.node('NodeGroupInput'); out = g.node('NodeGroupOutput')
    call = g.node('GeometryNodeGroup', 'Shared original coordinate arithmetic')
    call.node_tree = core
    for key in ('Corners', 'Mouths', 'Index', 't', 'v', 'Boundary Valid'):
        g.bind(inp.outputs[key], call.inputs[key])
    g.bind(external_ratio, call.inputs['Use External Ratio'])
    for key in (('Depth Ratio', 'Ratio Derivative') if external_ratio else ('Guide Narrowing',)):
        g.bind(inp.outputs[key], call.inputs[key])
    if prepared_paths:
        for key in ('Path A', 'Path B')+(('Path Middle',) if span_compounds else ()):
            g.bind(inp.outputs[key], call.inputs[key])
    else:
        at = c.V(g, inp.outputs['Index'])
        indices = [at, g.math('MODULO', at+1., c._count(g, inp.outputs['Mouths']))]
        if span_compounds:
            indices.append(c._read(g, inp.outputs['Corners'], 'st_pc_mid_port', at, 'INT'))
        valid = 1.
        for key, index in zip(('Path A', 'Path B', 'Path Middle'), indices):
            source = boundary._source(g, inp, index, port_paths=True, interpolation=interpolation)
            table = boundary._table(g, source)
            g.bind(table.outputs['Geometry'], call.inputs[key])
            valid = valid*c.V(g, source.outputs['Valid'])*c.V(g, table.outputs['Valid'])
        g.bind(valid, call.inputs['Sources Valid'])
    for socket in out.inputs:
        if socket.name in call.outputs:
            g.bind(call.outputs[socket.name], socket)
        elif socket.bl_idname != 'NodeSocketVirtual':
            raise ValueError(('Unhandled original coordinate output', socket.name))
    if interface(original) != interface(tree):
        raise AssertionError('Shared coordinates changed the original socket interface')
    tree['st_shared_coordinates'] = 1
    return tree


def replace_references(roots):
    seen = set(); pending = list(roots)
    while pending:
        tree = pending.pop()
        if tree in seen: continue
        seen.add(tree)
        pending.extend(n.node_tree for n in tree.nodes if n.type == 'GROUP' and n.node_tree)
    rows = []
    for original in sorted(seen, key=lambda tree: tree.name):
        prefix = next((p for p in PREFIXES if original.name.startswith(p)), None)
        if prefix is None: continue
        suffix = original.name[len(prefix):]
        families = {
            ' / Taper v2 / Curb continuations v2 / Original Section ports v1': dict(continuations=True),
            ' / Taper v2 / Original Section ports v1 / Original span sides v1': dict(span_compounds=True),
        }
        interpolation = suffix.endswith(' / Exact entrance rays v1')
        if interpolation:
            suffix = suffix[:-len(' / Exact entrance rays v1')]
        if suffix not in families:
            raise ValueError(('Unrecognized coordinate variant', original.name))
        replacement = build(external_ratio=prefix != PREFIXES[0],
                            prepared_paths=prefix == PREFIXES[2], interpolation=interpolation,
                            **families[suffix])
        if interface(original) != interface(replacement):
            raise AssertionError(('Coordinate interface mismatch', original.name))
        rows.append(dict(original=original.name, replacement=replacement.name,
                         nodes_before=len(original.nodes), wrapper_nodes=len(replacement.nodes)))
        original.user_remap(replacement)
    if not rows: raise ValueError('No recognized coordinate calls were found')
    return rows
